// -------------------------------------------------------------------------
// block-level dispatch
// -------------------------------------------------------------------------

void smokemaxConstraints(double **uzipConsVars, const double **uZipVars,
                     const ot::Block *blkList, unsigned int numBlocks) {

    const Point pt_min(smokemax::SMOKEMAX_COMPD_MIN[0],
                       smokemax::SMOKEMAX_COMPD_MIN[1],
                       smokemax::SMOKEMAX_COMPD_MIN[2]);
    const Point pt_max(smokemax::SMOKEMAX_COMPD_MAX[0],
                       smokemax::SMOKEMAX_COMPD_MAX[1],
                       smokemax::SMOKEMAX_COMPD_MAX[2]);
    const Point oct_min(smokemax::SMOKEMAX_OCTREE_MIN[0],
                        smokemax::SMOKEMAX_OCTREE_MIN[1],
                        smokemax::SMOKEMAX_OCTREE_MIN[2]);
    const Point oct_max(smokemax::SMOKEMAX_OCTREE_MAX[0],
                        smokemax::SMOKEMAX_OCTREE_MAX[1],
                        smokemax::SMOKEMAX_OCTREE_MAX[2]);

    // ot::BlockGeometryRange yields per-block offset/sz/bflag/dx/ptmin/ptmax and
    // hoists the grid->physical scaling out of the per-block loop.
    for (const auto &b : ot::BlockGeometryRange(blkList, numBlocks, pt_min,
                                                pt_max, oct_min, oct_max))
        smokemaxphyscon(uzipConsVars, uZipVars, b.offset, b.ptmin,
                                  b.ptmax, b.sz, b.bflag);
}

